      'rebuild path', () {
    final tx = TranscriptMarkdown(width: 60);
    final src = <String>['echo'];

    expectParityUnderDeltas(tx, src, [
      '| a | b |\n',
      '| 1 | 2 |\n',
      'tail:',
    ], 'close');

