  _pendingSeedTable = null;
  final s = _TableWalkState();
  s.pendingStart = seed == null || seed.isEmpty ? -1 : from - seed.length;
  for (var i = from; i < src.length; i++) {
    _walkStep(_fmt, src[i], i, s);
  }
  return _WalkResult(
    s.outsPerLine, s.lastClean, s.fenceAtClean, _fmt.hasPendingTable,
    _fmt.flushTrailing(), s.fenceAfter, s.tableBefore, s.pendingStartAt,
  );
}
