/// Directory spellings that must compare equal for the cwd == home
/// guard: trailing slashes are noise (`$HOME` can carry one, e.g.
/// `/home/user/` from some PAM setups), and duplicate inner slashes
/// appear when either side already ends in one. Lexical only — the
/// service is `dart:io`-free, so symlink resolution stays the host's
/// job (gh-1573 review thread).
static String _normalizeDir(String dir) {
  var d = dir;
  while (d.length > 1 && d.endsWith('/')) {
    d = d.substring(0, d.length - 1);
  }
  return d;
}
