Design a small private state class:

```dart
/// Per-step walk state shared by the incremental [_walk] and the full
/// [_rebuild] pass (gh-1573 boundary latch bookkeeping)...
final class _TableWalkState {
  _TableWalkState() : pendingStart = -1, lastClean = -1, fenceAtClean = false;
  int pendingStart;
  int lastClean;
  bool fenceAtClean;
  final List<bool> tableBefore = [];
  final List<int> pendingStartAt = [];
