        pendingStart = -1;
        lastClean = outs.length - 1;
        fenceAtClean = fmt.inFence;
      }
    }
    final hadPending = fmt.hasPendingTable;
    final trailing = fmt.flushTrailing();

    _fmt = fmt;
    _formatted = [];
    _rows = [];
