    // via removeLast, so fresh caches must already carry [0].
    _starts = [0];
    _srcFmtStarts = [0];
    _srcRowStarts = [0];
    _fenceBeforeBoundaryLine = false;
    _through = 0;
    _boundaryFirst = src.isEmpty ? null : src.first;
    _boundaryLast = src.isEmpty ? null : src.last;
    _savedFence = false;
