    // This step may have OPENED the span (buffered its first row).
    if (s.pendingStart < 0) s.pendingStart = i;
  } else {
    s.pendingStart = -1;
    s.lastClean = s.outsPerLine.length - 1;
    s.fenceAtClean = fmt.inFence;
  }
